{%- set ns = namespace(l=[]) -%}
{%- for name, g in (state_attr('sensor.einkauf_verlauf', 'grundartikel') or {}).items() if g.preis is defined or g.wochen is defined -%}
{%- set d = {'artikel': name} -%}
{%- set d = dict(d, normalpreis=g.preis) if g.preis is defined else d -%}
{%- set d = dict(d, wochen=g.wochen) if g.wochen is defined else d -%}
{%- set ns.l = ns.l + [d] -%}
{%- endfor -%}
